import "jsr:@supabase/functions-js/edge-runtime.d.ts"
import { createClient } from "npm:@supabase/supabase-js@2"
import { isMtapiConfigured, MtapiClient } from "../_shared/mtapiClient.ts"

/**
 * Migration-preview social copy reconciler.
 *
 * Opens new source positions, syncs SL/TP (and partial closes) on existing
 * mappings, and closes follower tickets when the provider position disappears.
 * Workers with SOCIAL_COPY_EXECUTION_ENABLED may also claim the same
 * subscriptions; lease skip-locked prevents double work.
 */

const WORKER_ID = "social-copy-edge"

type SubRow = {
  id: string
  source_id: string
  destination_broker_account_id: string
  sizing_mode: "fixed_lot" | "lot_multiplier" | "equity_ratio"
  fixed_lot: number | null
  lot_multiplier: number
  max_lot: number
  status: string
  desired_status: string
  execution_path: string
  source_account_mode: string
  destination_account_mode: string
  requested_account_mode: string
}

type BrokerRow = {
  id: string
  provider: string | null
  platform: string | null
  is_active: boolean
  connection_status: string | null
  mtapi_session_id: string | null
  linked_account_type: string | null
}

type MappingRow = {
  id: string
  source_ticket: string
  destination_ticket: string | null
  state: string
  source_volume: number | null
  destination_volume: number | null
  source_stop_loss: number | null
  source_take_profit: number | null
  broker_comment: string | null
}

function json(data: unknown, status = 200) {
  return Response.json(data, { status })
}

function num(value: unknown): number | null {
  const n = Number(value)
  return Number.isFinite(n) ? n : null
}

function isCopyEngineFillComment(raw: unknown): boolean {
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return false
  const row = raw as Record<string, unknown>
  const comment = String(row.comment ?? row.Comment ?? row.clientOrderId ?? "").trim().toLowerCase()
  return comment.startsWith("sc:") || comment.startsWith("mc:")
}

function normalizePosition(raw: unknown): {
  ticket: string
  symbol: string
  side: "buy" | "sell"
  volume: number
  stopLoss: number | null
  takeProfit: number | null
} | null {
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return null
  if (isCopyEngineFillComment(raw)) return null
  const row = raw as Record<string, unknown>
  const ticket = num(row.ticket ?? row.Ticket ?? row.order ?? row.Order)
  const symbol = String(row.symbol ?? row.Symbol ?? row.symbolName ?? "").trim()
  const sideText = `${row.orderType ?? row.OrderType ?? row.type ?? row.Type ?? row.cmd ?? ""}`.toLowerCase()
  const side = sideText.includes("buy") || sideText === "0"
    ? "buy"
    : sideText.includes("sell") || sideText === "1"
      ? "sell"
      : null
  const volume = num(row.lots ?? row.Lots ?? row.volume ?? row.Volume ?? row.lotsVolume)
  if (!(ticket && ticket > 0) || !symbol || !side || !(volume && volume > 0)) return null
  const stopLoss = num(row.stoploss ?? row.stopLoss ?? row.StopLoss ?? row.sl ?? row.SL)
  const takeProfit = num(row.takeprofit ?? row.takeProfit ?? row.TakeProfit ?? row.tp ?? row.TP)
  return {
    ticket: String(Math.trunc(ticket)),
    symbol,
    side,
    volume,
    stopLoss: stopLoss && stopLoss !== 0 ? stopLoss : null,
    takeProfit: takeProfit && takeProfit !== 0 ? takeProfit : null,
  }
}

function sizedVolume(sub: SubRow, sourceVolume: number): number {
  let requested = sub.sizing_mode === "fixed_lot"
    ? Number(sub.fixed_lot)
    : sourceVolume * Number(sub.lot_multiplier || 1)
  if (!(requested > 0)) requested = sourceVolume
  const maxLot = Number(sub.max_lot)
  if (maxLot > 0) requested = Math.min(requested, maxLot)
  // Round to 0.01 lots for MT5 demo safety.
  return Math.max(0.01, Math.floor(requested * 100 + 1e-9) / 100)
}

/**
 * Persist the provider's live MT position into `trades` so Social Trading
 * history / Copier Logs can show manual broker opens (not only channel signals).
 */
async function upsertSourceTrade(
  // deno-lint-ignore no-explicit-any
  supabase: any,
  input: {
    traderUserId: string
    brokerAccountId: string
    position: {
      ticket: string
      symbol: string
      side: "buy" | "sell"
      volume: number
      stopLoss: number | null
      takeProfit: number | null
    }
  },
): Promise<void> {
  const ticket = input.position.ticket
  const { data: existing } = await supabase
    .from("trades")
    .select("id,status")
    .eq("broker_account_id", input.brokerAccountId)
    .eq("metaapi_order_id", ticket)
    .maybeSingle()
  if (existing?.id) {
    if (String(existing.status).toLowerCase() !== "open") {
      await supabase.from("trades").update({
        status: "open",
        closed_at: null,
        symbol: input.position.symbol,
        direction: input.position.side,
        lot_size: input.position.volume,
        sl: input.position.stopLoss,
        tp: input.position.takeProfit,
        broker_position_ticket: ticket,
      }).eq("id", existing.id)
    }
    return
  }
  const { error } = await supabase.from("trades").insert({
    user_id: input.traderUserId,
    broker_account_id: input.brokerAccountId,
    signal_id: null,
    metaapi_order_id: ticket,
    broker_position_ticket: ticket,
    symbol: input.position.symbol,
    direction: input.position.side,
    lot_size: input.position.volume,
    status: "open",
    opened_at: new Date().toISOString(),
    sl: input.position.stopLoss,
    tp: input.position.takeProfit,
  })
  if (error && !String(error.message).toLowerCase().includes("duplicate")) {
    console.warn("[social-copy-reconcile] source trade upsert failed", error.message)
  }
}

async function closeSourceTrade(
  // deno-lint-ignore no-explicit-any
  supabase: any,
  brokerAccountId: string,
  sourceTicket: string,
): Promise<void> {
  const { error } = await supabase.from("trades").update({
    status: "closed",
    closed_at: new Date().toISOString(),
  }).eq("broker_account_id", brokerAccountId).eq("metaapi_order_id", sourceTicket).eq("status", "open")
  if (error) {
    console.warn("[social-copy-reconcile] source trade close failed", error.message)
  }
}

/** Persist an audit row so Copier Logs / Activities can show the copy. */
async function writeExecutionEvent(
  // deno-lint-ignore no-explicit-any
  supabase: any,
  input: {
    subscriptionId: string
    mappingId: string | null
    sourceTicket: string
    action: "open" | "close" | "modify"
    idempotencyKey: string
    status: "succeeded" | "failed" | "uncertain"
    request: Record<string, unknown>
    result?: Record<string, unknown>
    errorDetail?: string | null
  },
): Promise<void> {
  let eventId: string | undefined
  const { data, error } = await supabase.from("social_copy_execution_events").insert({
    subscription_id: input.subscriptionId,
    mapping_id: input.mappingId,
    source_ticket: input.sourceTicket,
    action: input.action,
    idempotency_key: input.idempotencyKey,
    status: "claimed",
    request_payload: input.request,
  }).select("id").single()

  if (error?.code === "23505") {
    // Rematerialize after a cleared dead mapping — prior attempts often finished
    // as failed/uncertain and must not permanently block a successful retry.
    const { data: existing } = await supabase.from("social_copy_execution_events")
      .select("id,status,attempt_count")
      .eq("subscription_id", input.subscriptionId)
      .eq("idempotency_key", input.idempotencyKey)
      .maybeSingle()
    const prior = String(existing?.status ?? "")
    if (!existing?.id || (prior !== "failed" && prior !== "uncertain")) return
    eventId = String(existing.id)
    await supabase.from("social_copy_execution_events").update({
      status: "claimed",
      attempt_count: Number(existing.attempt_count ?? 1) + 1,
      mapping_id: input.mappingId,
      request_payload: input.request,
      error_code: null,
      error_detail: null,
      completed_at: null,
    }).eq("id", eventId)
  } else if (error) {
    console.warn("[social-copy-reconcile] event insert failed", error.message)
    return
  } else {
    eventId = data?.id as string | undefined
  }
  if (!eventId) return

  const { error: updateError } = await supabase.from("social_copy_execution_events").update({
    status: input.status,
    result_payload: input.result ?? {},
    error_detail: input.errorDetail ?? null,
    completed_at: new Date().toISOString(),
  }).eq("id", eventId)
  if (updateError) {
    console.warn("[social-copy-reconcile] event finish failed", updateError.message)
  }
}

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") return new Response("ok")

  const auth = req.headers.get("Authorization") ?? ""
  const token = auth.replace(/^Bearer\s+/i, "").trim()
  const serviceKey = (Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? "").trim()
  if (!token) return json({ error: "Service role required" }, 401)

  // Accept the project service-role key, or any JWT whose role claim is service_role
  // (cron / vault keys can differ from a local preview copy of the secret).
  let authorized = Boolean(serviceKey) && token === serviceKey
  if (!authorized && token.split(".").length === 3) {
    try {
      const payload = JSON.parse(atob(token.split(".")[1]!.replace(/-/g, "+").replace(/_/g, "/")))
      authorized = payload?.role === "service_role"
    } catch {
      authorized = false
    }
  }
  if (!authorized) return json({ error: "Service role required" }, 401)

  if (!isMtapiConfigured(Deno.env)) {
    return json({ error: "MTAPI is not configured on this project" }, 503)
  }

  const supabase = createClient(
    Deno.env.get("SUPABASE_URL")!,
    serviceKey || token,
    { auth: { persistSession: false, autoRefreshToken: false } },
  )
  const mtapi = new MtapiClient({ env: Deno.env })

  const { data: claimed, error: claimError } = await supabase.rpc("claim_social_copy_subscriptions", {
    p_worker: WORKER_ID,
    p_limit: 10,
    p_lease_seconds: 55,
  })
  if (claimError) return json({ error: claimError.message }, 500)

  const rows = (claimed ?? []) as SubRow[]
  const results: Array<Record<string, unknown>> = []

  for (const sub of rows) {
    try {
      if (sub.desired_status === "paused") {
        await supabase.from("social_copy_subscriptions").update({
          status: "paused",
          error_code: null,
          error_detail: null,
          lease_owner: null,
          lease_expires_at: null,
          last_reconciled_at: new Date().toISOString(),
          worker_acknowledged_at: new Date().toISOString(),
        }).eq("id", sub.id)
        results.push({ id: sub.id, status: "paused" })
        continue
      }
      if (sub.desired_status === "stopped") {
        await supabase.from("social_copy_subscriptions").update({
          status: "stopped",
          stopped_at: new Date().toISOString(),
          lease_owner: null,
          lease_expires_at: null,
          last_reconciled_at: new Date().toISOString(),
        }).eq("id", sub.id)
        results.push({ id: sub.id, status: "stopped" })
        continue
      }
      if (sub.execution_path !== "broker") {
        await supabase.from("social_copy_subscriptions").update({
          status: "active",
          error_code: null,
          error_detail: null,
          lease_owner: null,
          lease_expires_at: null,
          last_reconciled_at: new Date().toISOString(),
          worker_acknowledged_at: new Date().toISOString(),
        }).eq("id", sub.id)
        results.push({ id: sub.id, status: "synthetic_ack" })
        continue
      }

      const { data: authorized, error: authErr } = await supabase.rpc(
        "check_social_copy_subscription_authorization",
        { p_subscription_id: sub.id },
      )
      if (authErr || authorized !== true) {
        throw new Error("SOCIAL_ACCESS_REVOKED")
      }

      const { data: source } = await supabase.from("social_copy_sources")
        .select("id,broker_account_id,status,trader_user_id")
        .eq("id", sub.source_id)
        .single()
      if (!source || source.status !== "published") throw new Error("SOURCE_NOT_PUBLISHED")
      const traderUserId = String(source.trader_user_id ?? "").trim()

      const [{ data: sourceBroker }, { data: destBroker }] = await Promise.all([
        supabase.from("broker_accounts")
          .select("id,provider,platform,is_active,connection_status,mtapi_session_id,linked_account_type")
          .eq("id", source.broker_account_id)
          .single(),
        supabase.from("broker_accounts")
          .select("id,provider,platform,is_active,connection_status,mtapi_session_id,linked_account_type")
          .eq("id", sub.destination_broker_account_id)
          .single(),
      ])
      const src = sourceBroker as BrokerRow | null
      const dst = destBroker as BrokerRow | null
      if (!src?.is_active || !dst?.is_active) throw new Error("BROKER_DISCONNECTED")
      if (String(src.provider).toLowerCase() !== "mtapi" || String(dst.provider).toLowerCase() !== "mtapi") {
        throw new Error("UNSUPPORTED_PROVIDER")
      }
      const srcSession = String(src.mtapi_session_id ?? "").trim()
      const dstSession = String(dst.mtapi_session_id ?? "").trim()
      if (!srcSession || !dstSession) throw new Error("BROKER_SESSION_UNAVAILABLE")

      const srcPlatform = String(src.platform ?? "MT5").toUpperCase()
      const dstPlatform = String(dst.platform ?? "MT5").toUpperCase()
      const sourceOrders = await mtapi.openedOrders(srcSession, srcPlatform)
      const positions = sourceOrders.map(normalizePosition).filter((row): row is NonNullable<typeof row> => row != null)

      // Mirror every live source position into `trades` so manual MT opens show in
      // Social Trading activities and Copier Logs — not only channel-copier fills.
      if (traderUserId) {
        for (const position of positions) {
          await upsertSourceTrade(supabase, {
            traderUserId,
            brokerAccountId: source.broker_account_id,
            position,
          })
        }
      }

      const { data: mappings } = await supabase.from("social_copy_trade_mappings")
        .select("id,source_ticket,destination_ticket,state,source_volume,destination_volume,source_stop_loss,source_take_profit,broker_comment")
        .eq("subscription_id", sub.id)
        .in("state", ["opening", "open", "closing", "uncertain", "error"])
      const bySource = new Map(((mappings ?? []) as MappingRow[]).map((row) => [row.source_ticket, row]))

      // Clear dead opens (null destination) while the source ticket is still live
      // so manual broker opens can rematerialize after a failed first attempt.
      // Leave `uncertain` alone — a broker fill may already exist.
      const liveTickets = new Set(positions.map((p) => p.ticket))
      for (const [ticket, mapping] of [...bySource.entries()]) {
        if (mapping.destination_ticket) continue
        if (mapping.state !== "error" && mapping.state !== "opening") continue
        if (!liveTickets.has(ticket)) continue
        await supabase.from("social_copy_trade_mappings").delete().eq("id", mapping.id)
        bySource.delete(ticket)
      }

      let opened = 0
      let modified = 0
      let closed = 0
      for (const position of positions) {
        const existing = bySource.get(position.ticket)
        if (existing) {
          // Sync SL/TP and partial closes onto the follower ticket.
          const destTicket = Number(existing.destination_ticket)
          if (!(Number.isFinite(destTicket) && destTicket > 0)) continue

          const mappedSourceVolume = Number(existing.source_volume ?? 0)
          const mappedDestVolume = Number(existing.destination_volume ?? 0)
          const volumeTolerance = Math.max(0.000001, Math.abs(mappedSourceVolume) * 0.0001)
          if (mappedSourceVolume > 0 && position.volume < mappedSourceVolume - volumeTolerance && mappedDestVolume > 0) {
            const targetDest = mappedDestVolume * (position.volume / mappedSourceVolume)
            const closeLots = Math.max(0.01, Math.floor((mappedDestVolume - targetDest) * 100 + 1e-9) / 100)
            if (closeLots > 0 && closeLots < mappedDestVolume) {
              try {
                await mtapi.orderCloseSafe(dstSession, { ticket: destTicket, lots: closeLots }, dstPlatform)
                const nextDest = Math.max(0.01, Math.floor((mappedDestVolume - closeLots) * 100 + 1e-9) / 100)
                await supabase.from("social_copy_trade_mappings").update({
                  source_volume: position.volume,
                  destination_volume: nextDest,
                }).eq("id", existing.id)
                existing.source_volume = position.volume
                existing.destination_volume = nextDest
                await writeExecutionEvent(supabase, {
                  subscriptionId: sub.id,
                  mappingId: existing.id,
                  sourceTicket: position.ticket,
                  action: "modify",
                  idempotencyKey: `resize:${position.ticket}:${position.volume}`,
                  status: "succeeded",
                  request: { closeVolume: closeLots },
                })
                modified += 1
              } catch (resizeError) {
                const detail = resizeError instanceof Error ? resizeError.message : String(resizeError)
                await writeExecutionEvent(supabase, {
                  subscriptionId: sub.id,
                  mappingId: existing.id,
                  sourceTicket: position.ticket,
                  action: "modify",
                  idempotencyKey: `resize:${position.ticket}:${position.volume}`,
                  status: "uncertain",
                  request: { closeVolume: closeLots },
                  errorDetail: detail.slice(0, 500),
                })
              }
            }
          }

          const mappedSl = existing.source_stop_loss == null ? null : Number(existing.source_stop_loss)
          const mappedTp = existing.source_take_profit == null ? null : Number(existing.source_take_profit)
          const slChanged = (mappedSl ?? null) !== (position.stopLoss ?? null)
          const tpChanged = (mappedTp ?? null) !== (position.takeProfit ?? null)
          if (slChanged || tpChanged) {
            try {
              await mtapi.orderModifySafe(dstSession, {
                ticket: destTicket,
                stoploss: position.stopLoss,
                takeprofit: position.takeProfit,
              }, dstPlatform)
              await supabase.from("social_copy_trade_mappings").update({
                source_stop_loss: position.stopLoss,
                source_take_profit: position.takeProfit,
              }).eq("id", existing.id)
              existing.source_stop_loss = position.stopLoss
              existing.source_take_profit = position.takeProfit
              await writeExecutionEvent(supabase, {
                subscriptionId: sub.id,
                mappingId: existing.id,
                sourceTicket: position.ticket,
                action: "modify",
                idempotencyKey: `modify:${position.ticket}:${position.stopLoss ?? 0}:${position.takeProfit ?? 0}`,
                status: "succeeded",
                request: { stopLoss: position.stopLoss, takeProfit: position.takeProfit },
              })
              modified += 1
            } catch (modifyError) {
              const detail = modifyError instanceof Error ? modifyError.message : String(modifyError)
              await writeExecutionEvent(supabase, {
                subscriptionId: sub.id,
                mappingId: existing.id,
                sourceTicket: position.ticket,
                action: "modify",
                idempotencyKey: `modify:${position.ticket}:${position.stopLoss ?? 0}:${position.takeProfit ?? 0}`,
                status: "failed",
                request: { stopLoss: position.stopLoss, takeProfit: position.takeProfit },
                errorDetail: detail.slice(0, 500),
              })
            }
          }
          continue
        }
        const volume = sizedVolume(sub, position.volume)
        const comment = `sc:${sub.id.slice(0, 8)}:${position.ticket}`.slice(0, 31)
        const { data: mappingInsert, error: mappingError } = await supabase.from("social_copy_trade_mappings").insert({
          subscription_id: sub.id,
          source_ticket: position.ticket,
          destination_ticket: null,
          source_symbol: position.symbol,
          destination_symbol: position.symbol,
          source_side: position.side,
          source_volume: position.volume,
          destination_volume: volume,
          source_stop_loss: position.stopLoss,
          source_take_profit: position.takeProfit,
          state: "opening",
          broker_comment: comment,
        }).select("id").single()
        if (mappingError) {
          if (String(mappingError.message).toLowerCase().includes("duplicate")) continue
          throw mappingError
        }
        try {
          const sent = await mtapi.orderSendSafe(dstSession, {
            symbol: position.symbol,
            operation: position.side === "buy" ? "Buy" : "Sell",
            volume,
            stoploss: position.stopLoss,
            takeprofit: position.takeProfit,
            comment,
          }, dstPlatform)
          await supabase.from("social_copy_trade_mappings").update({
            destination_ticket: String(sent.ticket),
            state: "open",
            opened_at: new Date().toISOString(),
            last_error_code: null,
            last_error_detail: null,
          }).eq("id", mappingInsert.id)
          await writeExecutionEvent(supabase, {
            subscriptionId: sub.id,
            mappingId: mappingInsert.id,
            sourceTicket: position.ticket,
            action: "open",
            idempotencyKey: `open:${position.ticket}`,
            status: "succeeded",
            request: {
              symbol: position.symbol,
              side: position.side,
              volume,
            },
            result: { destination_ticket: String(sent.ticket) },
          })
          opened += 1
        } catch (openError) {
          const detail = openError instanceof Error ? openError.message : String(openError)
          await supabase.from("social_copy_trade_mappings").update({
            state: "error",
            last_error_code: "BROKER_OPERATION_FAILED",
            last_error_detail: detail.slice(0, 500),
          }).eq("id", mappingInsert.id)
          await writeExecutionEvent(supabase, {
            subscriptionId: sub.id,
            mappingId: mappingInsert.id,
            sourceTicket: position.ticket,
            action: "open",
            idempotencyKey: `open:${position.ticket}`,
            status: "failed",
            request: {
              symbol: position.symbol,
              side: position.side,
              volume,
            },
            errorDetail: detail.slice(0, 500),
          })
          // Keep reconciling other tickets — next tick clears this dead mapping
          // while the source position is still open and retries the open.
          console.warn("[social-copy-reconcile] open failed", position.ticket, detail)
          continue
        }
      }

      const openTickets = new Set(positions.map((p) => p.ticket))
      for (const mapping of bySource.values()) {
        if (openTickets.has(mapping.source_ticket) || mapping.state === "closed") continue
        const destTicket = Number(mapping.destination_ticket)
        if (Number.isFinite(destTicket) && destTicket > 0) {
          try {
            await mtapi.orderCloseSafe(dstSession, { ticket: destTicket }, dstPlatform)
          } catch {
            // Already closed on broker is fine; mark mapping closed either way.
          }
        }
        await supabase.from("social_copy_trade_mappings").update({
          state: "closed",
          closed_at: new Date().toISOString(),
        }).eq("id", mapping.id)
        await closeSourceTrade(supabase, source.broker_account_id, mapping.source_ticket)
        await writeExecutionEvent(supabase, {
          subscriptionId: sub.id,
          mappingId: mapping.id,
          sourceTicket: mapping.source_ticket,
          action: "close",
          idempotencyKey: `close:${mapping.source_ticket}`,
          status: "succeeded",
          request: { destination_ticket: mapping.destination_ticket },
        })
        closed += 1
      }

      await supabase.from("social_copy_subscriptions").update({
        status: "active",
        error_code: null,
        error_detail: null,
        lease_owner: null,
        lease_expires_at: null,
        last_reconciled_at: new Date().toISOString(),
        worker_acknowledged_at: new Date().toISOString(),
      }).eq("id", sub.id)
      results.push({ id: sub.id, status: "active", opened, modified, closed, sourceOpen: positions.length })
    } catch (cause) {
      const detail = cause instanceof Error ? cause.message : String(cause)
      const code = detail.includes("SOCIAL_ACCESS_REVOKED")
        ? "SOCIAL_ACCESS_REVOKED"
        : detail.includes("SESSION") || detail.toLowerCase().includes("connect")
          ? "BROKER_DISCONNECTED"
          : "BROKER_OPERATION_FAILED"
      await supabase.from("social_copy_subscriptions").update({
        status: "error",
        error_code: code,
        error_detail: detail.slice(0, 500),
        lease_owner: null,
        lease_expires_at: null,
        last_reconciled_at: new Date().toISOString(),
      }).eq("id", sub.id)
      results.push({ id: sub.id, status: "error", error: detail })
    }
  }

  return json({ ok: true, processed: results.length, results })
})

/**
 * Minimal MTAPI HTTP client for Deno edge functions.
 *
 * Endpoints mirror worker MtapiProvider shapes. Session preparation uses
 * ConnectEx, CheckConnect, AccountSummary, and Disconnect.
 * Session id is passed as `?id=` (same protocol as the worker bridge).
 */

import { redactBridgeSecrets } from "./mtapiRedaction.ts"

export class MtapiApiError extends Error {
  constructor(message: string, readonly status: number, readonly code?: string) {
    // Single choke point: the `mtapi-broker` handler returns this message to
    // the caller, so without redaction the MT4 bridge's echoed credentials
    // would land in the customer's browser.
    super(redactBridgeSecrets(message))
    this.name = "MtapiApiError"
    // `code` is redacted as well because `errorDetails` promotes a bare-string
    // `error` body field into it, and `mtapiFailureSummary()` forwards an
    // unmatched code verbatim into `broker_accounts.connection_error`.
    if (this.code != null) this.code = redactBridgeSecrets(this.code)
  }
}

function envString(env: Deno.Env, name: string): string {
  return String(env.get(name) ?? "").trim()
}

export function isMtapiConfigured(env: Deno.Env): boolean {
  return Boolean(
    envString(env, "MTAPI_BASE_URL")
    || envString(env, "MTAPI_MT4_BASE_URL")
    || envString(env, "MTAPI_MT5_BASE_URL"),
  )
}

function baseUrl(env: Deno.Env, platform?: string | null): string {
  const platformUpper = String(platform ?? "MT5").toUpperCase()
  const specific = envString(env, platformUpper === "MT4" ? "MTAPI_MT4_BASE_URL" : "MTAPI_MT5_BASE_URL")
  const base = (specific || envString(env, "MTAPI_BASE_URL")).replace(/\/+$/, "")
  if (!base) {
    throw new MtapiApiError(
      "MTAPI is not configured. Set MTAPI_BASE_URL in Supabase Edge secrets.",
      503,
      "NOT_CONFIGURED",
    )
  }
  return base
}

function object(value: unknown): Record<string, unknown> {
  return value != null && typeof value === "object" && !Array.isArray(value)
    ? value as Record<string, unknown>
    : {}
}

function errorDetails(value: unknown): { code?: string; message?: string } {
  const row = object(value)
  const rawError = row.error ?? row.Error
  const nested = object(rawError)
  const code = row.code ?? row.Code ?? nested.code ?? nested.Code
    ?? (typeof rawError === "string" ? rawError : undefined)
  const message = row.message ?? row.Message ?? row.errorMessage ?? nested.message ?? nested.Message
  return {
    code: code == null ? undefined : String(code),
    message: message == null ? undefined : String(message),
  }
}

function list(value: unknown, keys: string[], endpoint: string): unknown[] {
  if (Array.isArray(value)) return value
  const row = object(value)
  for (const key of keys) if (Array.isArray(row[key])) return row[key] as unknown[]
  const result = row.result ?? row.Result
  if (Array.isArray(result)) return result
  const nested = object(result)
  for (const key of keys) if (Array.isArray(nested[key])) return nested[key] as unknown[]
  throw new MtapiApiError(endpoint + " returned an invalid list response", 502, "INVALID_RESPONSE")
}

export interface MtapiClientOptions {
  env: Deno.Env
  fetchImpl?: typeof fetch
  timeoutMs?: number
}

/**
 * Read methods share the FxSocket client signatures used by fxsocketTrades
 * (session id + optional platform), so one trades pipeline serves both providers.
 */
export class MtapiClient {
  /**
   * Closed trade rows are served from OrderHistory: bridge sessions are
   * connected without `downloadOrderHistory`, so HistoryPositions fails with
   * ORDER_HISTORY_NOT_READY. See MtHistorySource.closedHistorySource.
   */
  readonly closedHistorySource = "order_history" as const

  private readonly env: Deno.Env
  private readonly fetchImpl: typeof fetch
  private readonly timeoutMs: number

  constructor(options: MtapiClientOptions) {
    this.env = options.env
    this.fetchImpl = options.fetchImpl ?? fetch
    this.timeoutMs = options.timeoutMs ?? 30_000
  }

  async connectEx(args: {
    server: string
    login: string
    password: string
    platform: "MT4" | "MT5"
  }): Promise<string> {
    const body = await this.request("ConnectEx", {
      user: args.login,
      password: args.password,
      server: args.server,
    }, "", args.platform)
    const token = String(body ?? "").trim().replace(/^["']|["']$/g, "")
    if (!token || token === "[object Object]") {
      throw new MtapiApiError(
        "MTAPI ConnectEx returned no session token",
        502,
        "INVALID_RESPONSE",
      )
    }
    return token
  }

  async checkConnect(sessionId: string, platform: "MT4" | "MT5"): Promise<void> {
    const body = await this.request("CheckConnect", {}, sessionId, platform)
    if (typeof body === "string" && body.trim().toUpperCase() === "OK") return
    throw new MtapiApiError(
      "MTAPI CheckConnect returned an invalid response",
      502,
      "INVALID_RESPONSE",
    )
  }

  async disconnect(sessionId: string, platform: "MT4" | "MT5"): Promise<void> {
    await this.request("Disconnect", {}, sessionId, platform)
  }

  private async request(
    endpoint: string,
    params: Record<string, string | number | boolean | null | undefined>,
    sessionId: string,
    platform?: string | null,
    timeoutMs?: number,
  ): Promise<unknown> {
    const url = new URL(baseUrl(this.env, platform) + "/" + endpoint)
    for (const [key, value] of Object.entries(params)) {
      if (value !== undefined && value !== null && value !== "") {
        url.searchParams.set(key, String(value))
      }
    }
    if (sessionId) url.searchParams.set("id", sessionId)

    const headers: Record<string, string> = { accept: "application/json, text/plain" }
    const proxyKey = envString(this.env, "MTAPI_PROXY_KEY") || envString(this.env, "MTAPI_API_KEY")
    if (proxyKey) headers["Authorization"] = "Bearer " + proxyKey
    const internalToken = envString(this.env, "MTAPI_INTERNAL_TOKEN")
    if (internalToken) headers["X-Internal-Token"] = internalToken

    const controller = new AbortController()
    const timer = setTimeout(() => controller.abort(), timeoutMs ?? this.timeoutMs)
    try {
      const response = await this.fetchImpl(url, {
        method: "GET",
        headers,
        signal: controller.signal,
      })
      const text = await response.text()
      let body: unknown = text
      if (text.trim().startsWith("{") || text.trim().startsWith("[")) {
        try {
          body = JSON.parse(text)
        } catch {
          /* caller validates shape */
        }
      }
      const details = errorDetails(body)
      if (!response.ok || details.code) {
        const containsCredential = params.password !== undefined && params.password !== null
        throw new MtapiApiError(
          containsCredential
            ? "MTAPI " + endpoint + " failed"
            : details.message || details.code || ("MTAPI " + endpoint + " failed"),
          response.status,
          details.code,
        )
      }
      return body
    } catch (error) {
      if (error instanceof MtapiApiError) throw error
      const message = error instanceof Error && error.name === "AbortError"
        ? "MTAPI " + endpoint + " timed out"
        : "MTAPI " + endpoint + " request failed"
      throw new MtapiApiError(message, 503, "TRANSPORT_ERROR")
    } finally {
      clearTimeout(timer)
    }
  }

  async openedOrders(sessionId: string, platform?: string | null): Promise<unknown[]> {
    const raw = await this.request("OpenedOrders", {}, sessionId, platform)
    return list(raw, ["orders", "Orders"], "OpenedOrders")
  }

  async closedOrders(sessionId: string, platform?: string | null): Promise<unknown[]> {
    const raw = await this.request("ClosedOrders", {}, sessionId, platform)
    return list(raw, ["orders", "Orders"], "ClosedOrders")
  }

  async orderHistory(
    sessionId: string,
    from: string,
    to: string,
    platform?: string | null,
  ): Promise<unknown[]> {
    const startedAt = Date.now()
    const raw = await this.request(
      "OrderHistory",
      { from, to },
      sessionId,
      platform,
      90_000,
    )
    const rows = list(raw, ["orders", "Orders"], "OrderHistory")
    if (object(raw).partialResponse !== true) return rows

    // The bridge truncated the response — re-read through the paginated
    // endpoint so large histories stay complete (mirrors the worker's
    // orderHistoryPage flow). Safety cap: 40 pages × 500 rows = 20k rows,
    // windowed to the newest pages (start = pagesCount - maxPages) like the
    // worker. Pages are fetched NEWEST-FIRST so a budget cut or a mid-loop
    // failure keeps the most recent rows (consumers dedupe by ticket and
    // re-sort by time, so row order does not matter), and page 0's probe
    // rows are reused when page 0 is inside the window. Budget: 30s from
    // now but never past 115s from method entry, so the 120s client-side
    // edge-call timeout still wins over this whole read; on expiry return
    // what we have (never throw) — this runs every 15s poll. If the
    // paginated endpoint is unavailable, keep the truncated rows rather
    // than failing the whole read. `ascending: true` is pinned so the
    // newest-window selection never depends on the bridge default.
    const all: unknown[] = []
    try {
      const ordersPerPage = 500
      const maxPages = 40
      const deadline = Math.min(startedAt + 115_000, Date.now() + 30_000)
      const pageTimeoutMs = () => Math.max(1_000, Math.min(90_000, deadline - Date.now()))
      const page0 = object(await this.request(
        "OrderHistoryPagination",
        { from, to, pageNumber: 0, ordersPerPage, ascending: true },
        sessionId,
        platform,
        pageTimeoutMs(),
      ))
      const rawPages = Number(page0.pagesCount ?? page0.PagesCount ?? page0.totalPages)
      const pagesCount = Number.isFinite(rawPages) ? Math.max(1, Math.floor(rawPages)) : 1
      const start = Math.max(0, pagesCount - maxPages)
      if (start > 0) {
        console.warn(
          `[mtapiClient] OrderHistory pagination capped at ${maxPages}/${pagesCount} pages — reading the newest window (pages ${start}..${pagesCount - 1})`,
        )
      }
      // Page 0 doubles as the pagesCount probe; reuse its rows when it is
      // inside the window (oldest page, already paid for) instead of
      // refetching it at the end of the loop.
      const reuseProbe = start === 0
      if (reuseProbe) {
        all.push(...list(page0, ["orders", "Orders"], "OrderHistoryPagination"))
      }
      const loopFloor = reuseProbe ? 1 : start
      for (let pageNumber = pagesCount - 1; pageNumber >= loopFloor; pageNumber -= 1) {
        // Always attempt the newest page (first iteration) even if the
        // probe already burned the budget; check the deadline after that.
        if (pageNumber !== pagesCount - 1 && Date.now() >= deadline) {
          console.warn(
            `[mtapiClient] OrderHistory pagination stopped after ${all.length} rows (${rows.length} truncated) — pagination budget exhausted`,
          )
          break
        }
        const next = await this.request(
          "OrderHistoryPagination",
          { from, to, pageNumber, ordersPerPage, ascending: true },
          sessionId,
          platform,
          pageTimeoutMs(),
        )
        all.push(...list(next, ["orders", "Orders"], "OrderHistoryPagination"))
      }
      if (all.length === 0 && rows.length > 0) {
        console.warn(
          `[mtapiClient] OrderHistoryPagination returned no rows — keeping ${rows.length} truncated rows`,
        )
        return rows
      }
      console.warn(
        `[mtapiClient] OrderHistory partialResponse=true — read ${all.length} rows via OrderHistoryPagination`,
      )
      return all
    } catch (err) {
      console.warn(
        `[mtapiClient] OrderHistoryPagination failed (${err instanceof Error ? err.message : String(err)}) — returning ${all.length ? `${all.length} newest paginated rows` : `${rows.length} truncated rows`}`,
      )
      return all.length ? all : rows
    }
  }

  async positionHistory(
    sessionId: string,
    from: string,
    to: string,
    platform?: string | null,
  ): Promise<unknown[]> {
    if (String(platform ?? "").toUpperCase() === "MT4") {
      return await this.orderHistory(sessionId, from, to, platform)
    }
    const raw = await this.request(
      "HistoryPositions",
      { from, to },
      sessionId,
      platform,
      90_000,
    )
    return list(raw, ["positions", "Positions", "orders", "Orders"], "HistoryPositions")
  }

  async accountSummary(
    sessionId: string,
    platform?: string | null,
  ): Promise<Record<string, unknown>> {
    const row = object(await this.request("AccountSummary", {}, sessionId, platform))
    if (Object.keys(row).length === 0) {
      throw new MtapiApiError("AccountSummary returned an invalid response", 502, "INVALID_RESPONSE")
    }
    return row
  }

  async symbols(sessionId: string, platform?: string | null): Promise<string[]> {
    const raw = await this.request("Symbols", {}, sessionId, platform)
    if (Array.isArray(raw)) {
      return raw.map((value) => {
        if (typeof value === "string") return value
        const row = object(value)
        return String(row.symbol ?? row.Symbol ?? "")
      }).filter(Boolean)
    }
    const row = object(raw)
    if (Object.keys(row).length === 0) return []
    return Object.keys(row)
  }

  /** Raw integer contract; interpretation belongs to the explicitly verified adapter policy. */
  async serverTimezone(sessionId: string, platform?: string | null): Promise<unknown> {
    return await this.request("ServerTimezone", {}, sessionId, platform)
  }

  async accountDetails(
    sessionId: string,
    platform?: string | null,
  ): Promise<Record<string, unknown>> {
    const row = object(await this.request("AccountDetails", {}, sessionId, platform))
    if (Object.keys(row).length === 0) {
      throw new MtapiApiError("AccountDetails returned an invalid response", 502, "INVALID_RESPONSE")
    }
    return row
  }

  async priceHistory(
    sessionId: string,
    args: {
      symbol: string
      from: string
      to: string
      timeFrame: number
      timeoutSeconds?: number
    },
    platform: string | null = "MT5",
  ): Promise<unknown[]> {
    const raw = await this.request("PriceHistory", {
      symbol: args.symbol,
      from: args.from,
      to: args.to,
      timeFrame: args.timeFrame,
      timeoutSeconds: args.timeoutSeconds ?? 30,
    }, sessionId, platform, Math.max(45_000, ((args.timeoutSeconds ?? 30) + 10) * 1000))
    if (!Array.isArray(raw)) {
      throw new MtapiApiError("PriceHistory returned an invalid response", 502, "INVALID_RESPONSE")
    }
    return raw
  }

  async quoteHistory(
    sessionId: string,
    args: { symbol: string; timeframe: string; from: string; count: number },
    platform: string | null = "MT4",
  ): Promise<unknown[]> {
    const raw = await this.request("QuoteHistory", {
      symbol: args.symbol,
      timeframe: args.timeframe,
      from: args.from,
      count: args.count,
    }, sessionId, platform, 90_000)
    if (!Array.isArray(raw)) {
      throw new MtapiApiError("QuoteHistory returned an invalid response", 502, "INVALID_RESPONSE")
    }
    return raw
  }

  /** Market bid/ask for one symbol. Same shape as FxSocket getQuote. */
  async getQuote(
    sessionId: string,
    symbol: string,
    platform?: string | null,
  ): Promise<Record<string, unknown>> {
    const endpoint = String(platform ?? "").toUpperCase() === "MT4" ? "Quote" : "GetQuote"
    const row = object(await this.request(endpoint, { symbol }, sessionId, platform))
    const bid = Number(row.bid ?? row.Bid)
    const ask = Number(row.ask ?? row.Ask)
    if (!Number.isFinite(bid) || !Number.isFinite(ask) || bid <= 0 || ask <= 0) {
      throw new MtapiApiError(endpoint + " returned invalid prices", 502, "INVALID_RESPONSE")
    }
    const time = row.time ?? row.Time
    return {
      symbol: String(row.symbol ?? row.Symbol ?? symbol),
      bid,
      ask,
      time: time == null ? undefined : String(time),
    }
  }

  /**
   * Market OrderSendSafe used by Migration social-copy-reconcile.
   * Never retry on timeout — the terminal may have already accepted the order.
   */
  async orderSendSafe(
    sessionId: string,
    args: {
      symbol: string
      operation: "Buy" | "Sell"
      volume: number
      stoploss?: number | null
      takeprofit?: number | null
      slippage?: number | null
      comment?: string | null
    },
    platform?: string | null,
  ): Promise<{ ticket: number }> {
    const params: Record<string, string | number | boolean | null | undefined> = {
      symbol: args.symbol,
      operation: args.operation,
      volume: args.volume,
    }
    if (args.stoploss != null && args.stoploss !== 0) params.stoploss = args.stoploss
    if (args.takeprofit != null && args.takeprofit !== 0) params.takeprofit = args.takeprofit
    if (args.slippage != null) params.slippage = args.slippage
    if (args.comment) params.comment = args.comment
    const raw = object(await this.request("OrderSendSafe", params, sessionId, platform, 45_000))
    const ticket = Number(raw.ticket ?? raw.Ticket ?? raw.order ?? raw.Order)
    if (!Number.isFinite(ticket) || ticket <= 0) {
      throw new MtapiApiError("OrderSendSafe returned no valid broker ticket", 502, "INVALID_TICKET")
    }
    return { ticket: Math.trunc(ticket) }
  }

  async orderCloseSafe(
    sessionId: string,
    args: { ticket: number; lots?: number | null },
    platform?: string | null,
  ): Promise<void> {
    const params: Record<string, string | number | boolean | null | undefined> = {
      ticket: args.ticket,
    }
    if (args.lots != null && args.lots > 0) params.lots = args.lots
    await this.request("OrderCloseSafe", params, sessionId, platform, 45_000)
  }

  /** SL/TP (and optional price) modify used by social-copy-reconcile sync. */
  async orderModifySafe(
    sessionId: string,
    args: {
      ticket: number
      stoploss?: number | null
      takeprofit?: number | null
      price?: number | null
    },
    platform?: string | null,
  ): Promise<void> {
    const params: Record<string, string | number | boolean | null | undefined> = {
      ticket: args.ticket,
    }
    if (args.stoploss != null) params.stoploss = args.stoploss
    if (args.takeprofit != null) params.takeprofit = args.takeprofit
    if (args.price != null) params.price = args.price
    await this.request("OrderModifySafe", params, sessionId, platform, 45_000)
  }
}

/** Map raw MTAPI AccountSummary into the FxSocket summary shape used by the UI. */
export function normalizeMtapiAccountSummary(row: Record<string, unknown>): {
  balance?: number
  credit?: number
  profit?: number
  equity?: number
  margin?: number
  freeMargin?: number
  marginLevel?: number
  leverage?: number
  currency?: string
} {
  const num = (...keys: string[]): number | undefined => {
    for (const key of keys) {
      const v = row[key]
      if (v === undefined || v === null || v === "") continue
      const n = Number(v)
      if (Number.isFinite(n)) return n
    }
    return undefined
  }
  const currency = row.currency ?? row.Currency
  return {
    balance: num("balance", "Balance"),
    credit: num("credit", "Credit"),
    profit: num("profit", "Profit"),
    equity: num("equity", "Equity"),
    margin: num("margin", "Margin"),
    freeMargin: num("freeMargin", "FreeMargin"),
    marginLevel: num("marginLevel", "MarginLevel"),
    leverage: num("leverage", "Leverage"),
    currency: currency == null ? undefined : String(currency),
  }
}
